let nt=AC.currentTime+.1,st=0;const len=T_.sc.length,nf=d=>{const i=((d%len)+len)%len;return 440*Math.pow(2,(T_.r+T_.sc[i]+12*Math.floor(d/len)-69)/12)},sp=60/T_.bpm/2,ch_=[0,3,4,2];
