P.vy=Math.max(-7.5,Math.min(7.5,P.vy+.32*P.gd));const was=P.gr,lv=P.vy;P.gr=0;P.y+=P.vy;
for(const o of s)if(ov(o)){if(P.vy>0){P.y=o.y-P.h;if(P.gd>0){P.gr=1;if(o.sp)P.ride=o}}else if(P.vy<0){P.y=o.y+o.h;if(P.gd<0){P.gr=1;if(o.sp)P.ride=o}}P.vy=0}
if(P.gr&&!was&&Math.abs(lv)>2.5){sfx('land');P.landT=9;dust(P.x+6,P.y+(P.gd>0?P.h:0),Math.min(14,6+Math.abs(lv)|0),2)}
