if(P.jb>0&&P.coy>0){P.vy=-6.4*P.gd;P.jb=0;P.coy=0;P.landT=0;sfx('jump');dust(P.x+6,P.y+(P.gd>0?P.h:0),8,1.8)}
if(!K.j&&P.vy*P.gd<-2.2)P.vy*=.7;
P.fl--;if(K.fp&&P.fl<=0){P.gd*=-1;P.vy=P.gd*1.2;P.fl=16;P.gr=0;sfx('flip');shake=4;flash=.15;burst(P.x+6,P.y+9,24,'#b48cff',2.8);burst(P.x+6,P.y+9,10,'#f0e0ff',1.6);P.ft=15;fx.push({x:P.x+6,y:P.y+9,l:0});sf('flipped');ach('flip','Gravity Is Optional')}K.fp=0;
P.rot+=((P.gd<0?Math.PI:0)-P.rot)*.2;P.t++;animUpd();
