for(const p of parts){p.x+=p.vx;p.y+=p.vy;p.vx*=.96;p.vy*=.96;p.l--}parts=parts.filter(p=>p.l>0);fx.forEach(e=>e.l++);while(fx.length&&fx[0].l>22)fx.shift();
