/* ---------- UI ---------- */
function sh(id){document.querySelectorAll('.pn').forEach(p=>p.classList.toggle('on',p.id==id));$('#ov').className='on '+(mode=='title'?'':'dim')}
function hide(){$('#ov').className=''}
function pauseG(){if(mode!='play')return;setMode('pause');bk='pause';sh('pause');sfx('menu')}
function quests(){const f=S.flags,q=[['Escape the strange room',f.out],['Meet the girl in the yellow scarf',f.mira1],['Find the clockmaker in the east',f.tick1],['Find Tick\'s gear (things drift upward)',f.gear_given,f.tick1],['Silence the Broken Clock',f.ch1,f.gear_given],['Memory fragments '+S.frag.length+'/3 (optional)',S.frag.length>=3]];return q.filter(x=>x[2]===undefined||x[2]).map(x=>(x[1]?'[x] ':'[ ] ')+x[0]).join('<br>')}
function inv(){const it=[];if(S.items.includes('photo'))it.push('<b>Photograph</b> - "DAY 1. PLEASE REMEMBER."');if(S.items.includes('gear'))it.push("<b>Tick's Gear</b>");S.frag.forEach(n=>it.push('<b>Fragment</b> - '+FR[n]));
return (it.join('<br>')||'Nothing yet.')+'<br><br><b>Bonds</b> Mira '+S.rel.mira+' | Tick '+S.rel.tick+'<br><br><b>Achievements</b><br>'+(S.ach.length?S.ach.join(', '):'-')}
function startGame(s,intro){S=s;setMode('play');hide();$('#ch').innerHTML='';B=null;load(S.lvl,S.lvl=='boss'?60:undefined,S.lvl=='boss'?222:undefined);if(S.lvl=='boss'){S.lvl='village';load('village',2130,222)}fd.a=1;fd.d=-1;P.sleep=intro?1:0;P.wake=0;P.ft=0;P.an='idle';P.at=0;P.fr=intro?[3,8]:[0,0];
if(intro)say([['','Niko wakes up.'],['','A small room. Four walls. No door.'],['','On the wall, something is written.']],()=>{P.sleep=0;P.wake=54;sfx('menu')});else{toast('...welcome back. (Again?)');sf('back')}}
const ACT={new(){initA();startGame(newSave(),1)},cont(){const s=lsG('fi_s',0);if(!s)return;initA();startGame(s,0)},set(){bk='title';sh('set')},set2(){bk='pause';sh('set')},cred(){bk='title';sh('cred')},back(){sh(bk)},res(){hide();setMode('play')},
inv(){$('#invb').innerHTML=inv();sh('inv')},quest(){$('#qb').innerHTML=quests();sh('quest')},menu(){save();setMode('title');L=null;B=null;music('title');lang();sh('title')},keep(){S.lvl='village';setMode('play');hide();load('village',2130,222);S.cp=null},
full(){try{(document.documentElement.requestFullscreen||document.documentElement.webkitRequestFullscreen).call(document.documentElement);screen.orientation.lock('landscape').catch(()=>{})}catch(e){}},
reset(){const b=$('#brs');if(b.dataset.s){try{localStorage.removeItem('fi_s')}catch(e){}b.dataset.s='';lang();toast('Save deleted')}else{b.dataset.s=1;b.textContent=T[O.lang].sure}}};
$('#ov').addEventListener('click',e=>{const b=e.target.closest('button[data-a]');if(!b)return;initA();sfx('menu');ACT[b.dataset.a]&&ACT[b.dataset.a]()});
const ol=()=>{lsS('fi_o',O);vol()};
$('#sm').oninput=e=>{O.mus=+e.target.value;ol()};$('#ss').oninput=e=>{O.sfx=+e.target.value;ol();sfx('get')};$('#sn').oninput=e=>{O.sens=+e.target.value;ol()};$('#sx').onchange=e=>{O.mute=e.target.checked?1:0;ol()};$('#sl').onchange=e=>{O.lang=e.target.value;ol();lang()};
function bind(id,k){const e=$(id);e.addEventListener('pointerdown',ev=>{ev.preventDefault();initA();K[k]=1;if(k=='j')K.jp=1;if(k=='f')K.fp=1;if(k=='i')K.ip=1;e.classList.add('on')});['pointerup','pointercancel','pointerleave'].forEach(n=>e.addEventListener(n,()=>{K[k]=0;e.classList.remove('on')}))}
bind('#bl','l');bind('#br','r');bind('#bj','j');bind('#bf','f');bind('#bi','i');$('#bp').addEventListener('pointerdown',e=>{e.preventDefault();pauseG()});
cv.addEventListener('pointerdown',()=>{initA();if(mode=='talk')nextD()});
const KM={ArrowLeft:'l',KeyA:'l',ArrowRight:'r',KeyD:'r',ArrowUp:'j',KeyW:'j',Space:'j',KeyF:'f',ShiftLeft:'f',KeyE:'i',Enter:'i',ArrowDown:'d',KeyS:'d'};
addEventListener('keydown',e=>{if(e.code=='Escape'){mode=='play'?pauseG():mode=='pause'&&ACT.res();return}const k=KM[e.code];if(!k)return;e.preventDefault();initA();if(e.repeat)return;if(mode=='talk'&&(k=='j'||k=='i'))return nextD();K[k]=1;if(k=='j')K.jp=1;if(k=='f')K.fp=1;if(k=='i')K.ip=1});
addEventListener('keyup',e=>{const k=KM[e.code];if(k)K[k]=0});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseG()});
/* ---------- LOOP ---------- */
let last=0,acc=0;function loop(t){requestAnimationFrame(loop);acc+=Math.min(100,t-last);last=t;while(acc>=16.67){step();acc-=16.67}draw()}
lang();music('title');requestAnimationFrame(t=>{last=t;loop(t)});

